import{_ as t,o,c as s,ag as a}from"./chunks/framework.DqVSm8kp.js";const n="/llmxray/docs/educators/context-window.svg",r="/llmxray/docs/educators/token-budget.svg",i="/llmxray/docs/educators/memory-strategies.svg",y=JSON.parse('{"title":"Module 5: When Does the Model Forget?","description":"","frontmatter":{},"headers":[],"relativePath":"en/community/educators/module-5.md","filePath":"en/community/educators/module-5.md"}'),l={name:"en/community/educators/module-5.md"};function d(h,e,c,u,m,g){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="module-5-when-does-the-model-forget" tabindex="-1">Module 5: When Does the Model Forget? <a class="header-anchor" href="#module-5-when-does-the-model-forget" aria-label="Permalink to &quot;Module 5: When Does the Model Forget?&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>The Archaeologist</strong> — Excavate the boundaries of memory</p><p><strong>Duration:</strong> 60 min | <strong>Difficulty:</strong> Intermediate | <strong>Prerequisite:</strong> <a href="./module-1.html">Module 1</a>, <a href="./module-4.html">Module 4</a></p></div><h2 id="the-aha-moment" tabindex="-1">The Aha Moment <a class="header-anchor" href="#the-aha-moment" aria-label="Permalink to &quot;The Aha Moment&quot;">​</a></h2><blockquote><p>Context isn&#39;t memory — it&#39;s a sliding window. The model doesn&#39;t remember your conversation. It re-reads the entire transcript every time, and when it runs out of space, old messages simply vanish.</p></blockquote><p>This is the insight that dismantles the most pervasive illusion about AI assistants: that they &quot;remember&quot; you. When you chat with a language model, it feels like a continuous conversation with a being that recalls what you said five minutes ago. In reality, every single API call sends the <strong>entire conversation history</strong> from scratch. The model has no persistent internal state between calls — no memory register, no diary, no filing cabinet. It receives a block of text, generates a response, and immediately forgets everything.</p><p>The consequences are profound. There is a hard limit — the <strong>context window</strong> — on how much text fits in that block. When your conversation exceeds it, the oldest messages are silently dropped. The model does not gracefully summarize what it lost. It does not flag that it can no longer see your earlier instructions. Those messages simply cease to exist from the model&#39;s perspective, as if they were never written. Understanding this transforms how students design prompts, structure conversations, and evaluate the reliability of AI systems in production.</p><hr><h2 id="conceptual-background" tabindex="-1">Conceptual Background <a class="header-anchor" href="#conceptual-background" aria-label="Permalink to &quot;Conceptual Background&quot;">​</a></h2><h3 id="what-is-a-context-window" tabindex="-1">What is a context window? <a class="header-anchor" href="#what-is-a-context-window" aria-label="Permalink to &quot;What is a context window?&quot;">​</a></h3><p>A <strong>context window</strong> is the fixed-size buffer of tokens that a language model can process in a single call. It is not memory. It is not storage. It is more like a desk — there is only so much paper you can spread across it before things start falling off the edge.</p><p>Every time you send a message, the application assembles a single block of text containing:</p><ul><li>The system prompt (instructions for the model&#39;s behavior)</li><li>The full conversation history (every previous user message and assistant reply)</li><li>Your latest message</li></ul><p>This entire block is sent to the model as one input. The model reads it all, generates a response, and then <strong>retains nothing</strong>. The next time you send a message, the application rebuilds the block from scratch, now including the model&#39;s previous response as part of the history.</p><p>The context window defines the maximum size of this block, measured in tokens. If the assembled block exceeds the limit, something must be cut.</p><p><img src="'+n+'" alt="The Context Window"></p><h3 id="token-budget-who-gets-what" tabindex="-1">Token budget: who gets what? <a class="header-anchor" href="#token-budget-who-gets-what" aria-label="Permalink to &quot;Token budget: who gets what?&quot;">​</a></h3><p>The context window is a <strong>shared budget</strong>. Every component of the input competes for the same pool of tokens:</p><table tabindex="0"><thead><tr><th>Component</th><th>Typical token cost</th><th>Notes</th></tr></thead><tbody><tr><td><strong>System prompt</strong></td><td>50 - 500 tokens</td><td>Instructions, persona, rules</td></tr><tr><td><strong>Conversation history</strong></td><td>Grows with each turn</td><td>Each user + assistant turn adds tokens</td></tr><tr><td><strong>User&#39;s latest message</strong></td><td>10 - 500 tokens</td><td>The current query</td></tr><tr><td><strong>Reserved for reply</strong></td><td>Model-dependent</td><td>The model needs room to generate output</td></tr></tbody></table><p>Consider a model with a 4,096-token context window. If your system prompt consumes 200 tokens and you reserve 500 tokens for the model&#39;s reply, you have roughly 3,396 tokens for conversation history. If each turn (user message + assistant response) averages 300 tokens, you can fit about <strong>11 turns</strong> before the window is full.</p><p>With a 2,048-token window, that same setup leaves room for only about <strong>4-5 turns</strong>. The conversation fills up remarkably fast.</p><p>This is why system prompt length matters. A verbose system prompt that consumes 800 tokens steals space directly from your conversation history. Every token spent on instructions is a token unavailable for context.</p><p><img src="'+r+'" alt="Token Budget Breakdown"></p><div class="warning custom-block"><p class="custom-block-title">System prompts are invisible but expensive</p><p>Many AI applications inject large system prompts that users never see — persona definitions, safety guidelines, output formatting rules. These can consume hundreds or thousands of tokens before the user types a single word. When a model seems to &quot;forget&quot; earlier parts of your conversation, the hidden system prompt may be partly to blame.</p></div><h3 id="what-happens-when-context-overflows" tabindex="-1">What happens when context overflows? <a class="header-anchor" href="#what-happens-when-context-overflows" aria-label="Permalink to &quot;What happens when context overflows?&quot;">​</a></h3><p>When the assembled input exceeds the context window, the application must truncate it. The most common strategy is a <strong>sliding window</strong>: the oldest messages in the conversation history are dropped until the input fits.</p><p>This is not a graceful degradation. There is no &quot;fuzzy memory&quot; of older messages, no partial recall, no priority system that keeps the important parts. It is a hard cutoff:</p><ul><li><strong>Before truncation</strong>: The model can see messages 1 through 20</li><li><strong>After truncation</strong>: The model can see messages 8 through 20. Messages 1 through 7 are gone.</li></ul><p>The model has no awareness that anything was removed. It cannot tell you &quot;I used to know your name but I&#39;ve forgotten it.&quot; From its perspective, the conversation simply begins at message 8. If you told it your name in message 1 and asked for it in message 21, it would either confess ignorance or — worse — hallucinate a name.</p><p>This creates a class of subtle bugs in AI applications:</p><ul><li>Instructions given early in a conversation silently expire</li><li>The model contradicts its own earlier statements because it can no longer see them</li><li>Users experience the model as &quot;forgetful&quot; or &quot;inconsistent&quot; without understanding why</li></ul><h3 id="memory-strategies-fighting-the-forgetting" tabindex="-1">Memory strategies: fighting the forgetting <a class="header-anchor" href="#memory-strategies-fighting-the-forgetting" aria-label="Permalink to &quot;Memory strategies: fighting the forgetting&quot;">​</a></h3><p>Since the context window is fundamentally limited, applications use various strategies to preserve important information across longer conversations. LLMxRay implements a <strong>four-tier approach</strong>, each with different trade-offs:</p><p><strong>1. Sliding Window (default)</strong> The simplest strategy: keep the N most recent messages and drop everything older. Fast and predictable, but older context vanishes completely. You can configure the window size (e.g., 20 messages) in Chat Settings.</p><p><strong>2. Auto-Summarization</strong> When the conversation grows long, the application asks the model to summarize older messages into a condensed paragraph. This summary replaces the original messages, preserving the gist while using far fewer tokens. The trade-off: summaries lose nuance, exact quotes, and specific details.</p><p><strong>3. User Facts</strong> The application extracts and stores key facts from the conversation (names, preferences, stated goals) in a structured format outside the context window. These facts are injected into each new prompt as a compact &quot;memory&quot; section. This preserves critical information but only captures what the extraction logic identifies as important.</p><p><strong>4. RAG Message Memory</strong> Past messages are embedded as vectors and stored in IndexedDB. When the user sends a new message, the application searches for semantically similar past messages and injects the most relevant ones into the context. This is the most sophisticated strategy — it can surface information from hundreds of turns ago — but it depends on embedding quality and relevance matching.</p><p><img src="'+i+'" alt="Memory Strategies"></p><div class="warning custom-block"><p class="custom-block-title">No strategy is perfect</p><p>Every memory strategy is a lossy compression of the original conversation. Sliding window loses everything beyond the window. Summarization loses detail. User facts lose context. RAG retrieval may miss relevant messages or surface irrelevant ones. The fundamental constraint — a finite context window — cannot be fully overcome, only mitigated.</p></div><h3 id="context-length-across-models" tabindex="-1">Context length across models <a class="header-anchor" href="#context-length-across-models" aria-label="Permalink to &quot;Context length across models&quot;">​</a></h3><p>Models vary enormously in their context window size:</p><table tabindex="0"><thead><tr><th>Model</th><th>Context window</th><th>Approximate pages of text</th></tr></thead><tbody><tr><td>Older models (GPT-2 era)</td><td>1,024 tokens</td><td>~1.5 pages</td></tr><tr><td>LLaMA 2 (7B)</td><td>4,096 tokens</td><td>~6 pages</td></tr><tr><td>LLaMA 3 (8B)</td><td>8,192 tokens</td><td>~12 pages</td></tr><tr><td>Mistral 7B</td><td>32,768 tokens</td><td>~50 pages</td></tr><tr><td>GPT-4 Turbo</td><td>128,000 tokens</td><td>~200 pages</td></tr><tr><td>Claude, Gemini (latest)</td><td>200,000+ tokens</td><td>~300+ pages</td></tr></tbody></table><p>A natural reaction: &quot;Just make the context window bigger.&quot; But bigger is not always better:</p><ul><li><strong>Compute cost scales quadratically</strong> with context length in standard attention (O(n^2)). Doubling the context quadruples the compute for self-attention. Efficient attention variants (FlashAttention, grouped-query attention) mitigate this but do not eliminate it.</li><li><strong>Latency increases</strong> because the model must process more tokens before generating its first output token (higher TTFT).</li><li><strong>The &quot;lost in the middle&quot; problem</strong>: Liu et al. (2023) demonstrated that models are significantly worse at using information placed in the middle of long contexts compared to information at the beginning or end. Simply having a large context window does not guarantee the model will effectively use everything in it.</li><li><strong>Local models are constrained by VRAM</strong>. Running a 128K context on a consumer GPU may not be feasible. LLMxRay lets you set the context window in Chat Settings precisely because local hardware imposes real limits.</li></ul><hr><h2 id="hands-on-exercises" tabindex="-1">Hands-On Exercises <a class="header-anchor" href="#hands-on-exercises" aria-label="Permalink to &quot;Hands-On Exercises&quot;">​</a></h2><h3 id="exercise-1-fill-the-bucket" tabindex="-1">Exercise 1: Fill the bucket <a class="header-anchor" href="#exercise-1-fill-the-bucket" aria-label="Permalink to &quot;Exercise 1: Fill the bucket&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Open <strong>Chat Diagnostics</strong> in LLMxRay</li><li>Go to <strong>Chat Settings</strong> and set the context window to <strong>2,048 tokens</strong></li><li>Start a conversation — ask the model a series of questions on different topics</li><li>After each message, check the <strong>Metrics Dashboard</strong>: observe the <strong>prompt tokens</strong> count growing with each turn</li><li>Keep chatting until you notice the prompt tokens stop growing or old messages disappear from the context</li><li>Count how many total turns fit before the window was full</li><li>Now change the context window to <strong>8,192 tokens</strong> in Chat Settings and repeat the experiment</li></ol><div class="tip custom-block"><p class="custom-block-title">Use the /context slash command</p><p>You can quickly switch context window sizes by typing <code>/context 2048</code> or <code>/context 8192</code> in the chat input instead of navigating to Chat Settings each time.</p></div><p><strong>What you&#39;ll discover:</strong></p><p>With 2,048 tokens, the conversation fills up in roughly 4-7 turns depending on message length. With 8,192, you get roughly 4x as many turns. The relationship is approximately linear — double the context, double the conversation length.</p><p>Watch the Metrics Dashboard carefully: prompt tokens grow steadily, then plateau when the sliding window kicks in. That plateau is the moment older messages start vanishing.</p><p><strong>Record your observations:</strong></p><table tabindex="0"><thead><tr><th>Context window</th><th>Turns before full</th><th>Prompt tokens at plateau</th></tr></thead><tbody><tr><td>2,048</td><td>?</td><td>?</td></tr><tr><td>8,192</td><td>?</td><td>?</td></tr></tbody></table><hr><h3 id="exercise-2-the-amnesia-test" tabindex="-1">Exercise 2: The amnesia test <a class="header-anchor" href="#exercise-2-the-amnesia-test" aria-label="Permalink to &quot;Exercise 2: The amnesia test&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Set the context window to <strong>2,048 tokens</strong> in <strong>Chat Settings</strong></li><li>In your <strong>first message</strong>, tell the model: <em>&quot;My name is Alex and my favorite color is blue. Please remember this.&quot;</em></li><li>Have a conversation about <strong>unrelated topics</strong> — ask about history, science, cooking, anything. Send 5-10 messages.</li><li>After several turns, ask: <em>&quot;What is my name and what is my favorite color?&quot;</em></li><li>Does the model remember? Record the answer.</li><li>Now set the context window to <strong>8,192 tokens</strong> and repeat the entire experiment from step 2</li><li>At what point does the model forget with the larger context?</li></ol><p><strong>What you&#39;ll discover:</strong></p><p>With 2,048 tokens, the model will likely forget your name and color after just a few turns of unrelated conversation. The message containing your personal facts has been pushed out of the sliding window. The model may:</p><ul><li>Confess it doesn&#39;t know (&quot;I don&#39;t have that information&quot;)</li><li>Hallucinate an answer (confidently state an incorrect name)</li><li>Partially remember (get one fact right and one wrong)</li></ul><p>With 8,192 tokens, the facts survive longer — but they still eventually disappear if you chat long enough. The forgetting is <strong>inevitable</strong>; only the timing changes.</p><p><strong>The critical observation:</strong> The model does not know it has forgotten. It never says &quot;I used to know your name but it was removed from my context.&quot; It behaves as if the information never existed.</p><hr><h3 id="exercise-3-token-budget-anatomy" tabindex="-1">Exercise 3: Token budget anatomy <a class="header-anchor" href="#exercise-3-token-budget-anatomy" aria-label="Permalink to &quot;Exercise 3: Token budget anatomy&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Have a conversation of at least 5 turns in <strong>Chat Diagnostics</strong></li><li>Open the <strong>Prompt Inspector</strong> (prompt anatomy view)</li><li>Examine the <strong>stacked bar chart</strong> showing the token budget breakdown: system prompt tokens vs conversation history tokens vs user message tokens</li><li>Note the current system prompt size</li><li>Now go to <strong>Chat Settings</strong> and change the system prompt to something <strong>very long</strong> — paste a full paragraph of detailed instructions (e.g., <em>&quot;You are a helpful assistant who always responds in bullet points. You must cite sources for every claim. You should use formal academic English. You must never use contractions. Always begin your response with a summary sentence...&quot;</em> — make it 200+ words)</li><li>Send a new message and re-examine the Prompt Inspector</li><li>Compare: how much space does the expanded system prompt consume? How many fewer conversation turns fit?</li></ol><p><strong>What you&#39;ll discover:</strong></p><p>The stacked bar chart makes the trade-off viscerally clear. A short system prompt (e.g., &quot;You are a helpful assistant&quot;) might consume 10-20 tokens. A verbose system prompt can easily consume 300-500 tokens — that&#39;s 15-25% of a 2,048-token context window, gone before the conversation even starts.</p><p><strong>Reflection questions:</strong></p><ul><li>If you only have 2,048 tokens total, is a 500-token system prompt worth it?</li><li>How would you rewrite a long system prompt to convey the same instructions in fewer tokens?</li><li>What happens to the system prompt when context overflows — is it ever dropped?</li></ul><div class="warning custom-block"><p class="custom-block-title">The system prompt is usually protected</p><p>Most applications, including LLMxRay, protect the system prompt from truncation — it is always included. This means the system prompt permanently reduces the space available for conversation history. A bloated system prompt is a permanent tax on every turn of the conversation.</p></div><hr><h3 id="exercise-4-memory-strategies-comparison" tabindex="-1">Exercise 4: Memory strategies comparison <a class="header-anchor" href="#exercise-4-memory-strategies-comparison" aria-label="Permalink to &quot;Exercise 4: Memory strategies comparison&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Start a fresh conversation in <strong>Chat Diagnostics</strong> with the context window set to <strong>2,048 tokens</strong></li><li>In the first message, tell the model three specific facts: your name, your city, and your occupation</li><li>Have 8-10 turns of unrelated conversation</li><li>Ask the model to recall all three facts. Record what it remembers.</li><li>Now enable <strong>Sliding Window</strong> (set to 20 messages) in <strong>Chat Settings</strong> and repeat the experiment</li><li>Next, enable <strong>Auto-Summarization</strong> and repeat</li><li>Finally, enable <strong>RAG Message Memory</strong> and repeat</li><li>Compare results across all strategies</li></ol><p><strong>What you&#39;ll discover:</strong></p><table tabindex="0"><thead><tr><th>Strategy</th><th>Facts recalled (out of 3)</th><th>Token usage</th><th>Notes</th></tr></thead><tbody><tr><td>No strategy (raw)</td><td>?</td><td>High (grows unbounded)</td><td>Oldest messages simply dropped</td></tr><tr><td>Sliding Window (20)</td><td>?</td><td>Medium (capped)</td><td>Recent messages preserved, old ones gone</td></tr><tr><td>Auto-Summarization</td><td>?</td><td>Low (compressed)</td><td>Summary may or may not capture your facts</td></tr><tr><td>RAG Message Memory</td><td>?</td><td>Medium (selective)</td><td>Retrieves relevant past messages on demand</td></tr></tbody></table><p>The most revealing comparison is between Auto-Summarization and RAG Message Memory. Summarization compresses everything into a short paragraph, which might say &quot;the user introduced themselves&quot; without preserving the actual name. RAG retrieval can surface the exact original message containing your facts — but only if the retrieval query triggers a semantic match.</p><p><strong>Discussion:</strong></p><ul><li>Which strategy preserves the most context while using the fewest tokens?</li><li>Is there a strategy that works well for all conversation types, or does the best choice depend on the use case?</li><li>What would happen if you combined multiple strategies?</li></ul><hr><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ol><li><strong>The context window is a fixed-size buffer</strong>, not persistent memory. The model has no state between calls — the entire conversation is re-sent every time, and when it exceeds the limit, old messages are silently dropped.</li><li><strong>System prompts, conversation history, and the model&#39;s reply all compete</strong> for the same token budget. Every token spent on one component is unavailable to the others.</li><li><strong>Context overflow is a hard cutoff</strong>, not a gradual fade. The model has no awareness that messages were removed and cannot distinguish &quot;forgotten&quot; information from information that was never provided.</li><li><strong>Memory strategies are lossy workarounds</strong>, not solutions. Sliding window, summarization, user facts, and RAG retrieval each preserve different aspects of the conversation at different costs, but none fully replaces the original context.</li><li><strong>Bigger context windows help but are not a cure-all</strong>. They bring higher compute costs, increased latency, and the &quot;lost in the middle&quot; problem where models underuse information buried in long contexts.</li></ol><hr><h2 id="discussion-questions" tabindex="-1">Discussion Questions <a class="header-anchor" href="#discussion-questions" aria-label="Permalink to &quot;Discussion Questions&quot;">​</a></h2><ol><li>Why can&#39;t we just make context windows infinite? What are the computational, architectural, and practical barriers — and are any of them likely to be solved soon?</li><li>Many AI assistants claim to &quot;remember&quot; you across conversations. Given what you now know about context windows, what must be happening behind the scenes to create that illusion? What are the privacy implications?</li><li>In Module 4, you learned about RAG — retrieving relevant documents to augment the model&#39;s input. How does the context window limit affect RAG system design? What happens when the retrieved documents plus the conversation history exceed the context window?</li><li>If a model has a 128K context window, does that mean it can reliably use a 128K-token input? What does the &quot;lost in the middle&quot; research suggest about the effective vs theoretical context length?</li><li>Imagine you are building a customer support chatbot. A customer has a 50-message conversation spanning multiple issues. How would you design the memory strategy to ensure the model never forgets the customer&#39;s account details while still having room to discuss the current issue?</li></ol><hr><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><h3 id="academic-papers" tabindex="-1">Academic Papers <a class="header-anchor" href="#academic-papers" aria-label="Permalink to &quot;Academic Papers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Paper</th><th>Authors</th><th>Year</th><th>Link</th></tr></thead><tbody><tr><td>Attention Is All You Need</td><td>Vaswani, Shazeer, Parmar, Uszkoreit, Jones, Gomez, Kaiser, Polosukhin</td><td>2017</td><td><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">arXiv:1706.03762</a></td></tr><tr><td>Lost in the Middle: How Language Models Use Long Contexts</td><td>Liu, Lin, Hewitt, Paranjape, Bevilacqua, Petroni, Liang</td><td>2023</td><td><a href="https://arxiv.org/abs/2307.03172" target="_blank" rel="noreferrer">arXiv:2307.03172</a></td></tr><tr><td>Extending Context Window of Large Language Models via Positional Interpolation</td><td>Chen, Wong, Chen, Tian</td><td>2023</td><td><a href="https://arxiv.org/abs/2306.15595" target="_blank" rel="noreferrer">arXiv:2306.15595</a></td></tr><tr><td>LongRoPE: Extending LLM Context Window Beyond 2 Million Tokens</td><td>Ding, Zhang, Zhang, Xu, Shang, Yang, Nishi, Zheng, Bian</td><td>2024</td><td><a href="https://arxiv.org/abs/2402.13753" target="_blank" rel="noreferrer">arXiv:2402.13753</a></td></tr><tr><td>Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks</td><td>Lewis, Perez, Piktus, Petroni, Karpukhin, Goyal, Kuttler, Lewis, Yih, Rocktaschel, Riedel, Kiela</td><td>2020</td><td><a href="https://arxiv.org/abs/2005.11401" target="_blank" rel="noreferrer">arXiv:2005.11401</a></td></tr></tbody></table><h3 id="tutorials-and-visual-explanations" tabindex="-1">Tutorials and Visual Explanations <a class="header-anchor" href="#tutorials-and-visual-explanations" aria-label="Permalink to &quot;Tutorials and Visual Explanations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Resource</th><th>Author</th><th>Link</th></tr></thead><tbody><tr><td>Attention? Attention!</td><td>Lilian Weng</td><td><a href="https://lilianweng.github.io/posts/2018-06-24-attention/" target="_blank" rel="noreferrer">lilianweng.github.io</a></td></tr><tr><td>The Illustrated Transformer</td><td>Jay Alammar</td><td><a href="https://jalammar.github.io/illustrated-transformer/" target="_blank" rel="noreferrer">jalammar.github.io</a></td></tr></tbody></table><hr><h2 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h2><p><strong>Option A — Context window diary (individual, 1 page):</strong> Using LLMxRay&#39;s Chat Diagnostics, conduct the amnesia test (Exercise 2) with three different context window sizes (2,048 / 4,096 / 8,192). For each size, record the exact turn at which the model forgets your initial facts. Present your findings in a table and explain the relationship between context size and conversational memory. Include screenshots of the Metrics Dashboard showing the token growth curve.</p><p><strong>Option B — Memory strategy evaluation (pairs, 1 page):</strong> Test all four memory strategies (sliding window, auto-summarization, user facts, RAG message memory) using the same 15-turn conversation script. For each strategy, evaluate: (1) how many original facts were preserved, (2) total token usage, and (3) response quality. Present a comparison matrix and recommend which strategy is best suited for three different use cases: customer support, tutoring, and creative writing.</p><p><strong>Option C — System design proposal (groups of 2-3, 5-minute presentation):</strong> Design a memory architecture for an AI study assistant that helps students prepare for exams over multiple weeks of conversation. The assistant must remember the student&#39;s weak topics, track progress, and never forget key facts — all while running on a local model with a 4,096-token context window. Present your architecture, justify each memory strategy choice with evidence from your LLMxRay experiments, and demonstrate the trade-offs live.</p><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><p>In <strong><a href="./module-6.html">Module 6: Can AI Use Tools?</a></strong>, you&#39;ll explore tool calling — how language models can reach beyond text generation to execute code, search the web, query databases, and interact with external systems. You&#39;ll discover that tool use transforms the model from a text predictor into an agent, and you&#39;ll examine both the power and the risks of giving AI access to real-world actions.</p><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 5 of 8</strong> in the LLMxRay Educators Kit <a href="./module-4.html">← Module 4: What Does the Model See?</a> | <a href="./index.html">Back to Curriculum</a> | <a href="./module-6.html">Module 6: Can AI Use Tools? →</a></p></div>',103)])])}const f=t(l,[["render",d]]);export{y as __pageData,f as default};
